package dev.myjarvis.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class NotificationServiceTest extends ReminderTestSupport {
    @Test void getAndListNeverMarkOpenedAndExplicitOpenIsIdempotent(){UUID notification=deliver(create("ONCE"));assertEquals("CREATED",notifications.get(session,notification).get("status"));assertEquals("CREATED",((List<Map<String,Object>>)notifications.list(session,null,null,20).get("items")).getFirst().get("status"));assertNull(db.queryForObject("SELECT opened_at FROM notifications WHERE id=?",Object.class,notification));var created=java.time.Instant.parse(notifications.get(session,notification).get("created_at").toString());var opened=created.plusSeconds(1);var timed=inboxAt(opened);var first=timed.open(session,notification,body(Map.of()));var second=timed.open(session,notification,body(Map.of()));assertEquals(opened.toString(),first.get("opened_at"));assertFalse(java.time.Instant.parse(first.get("opened_at").toString()).isBefore(created));assertEquals(first,second);assertEquals("OPENED",first.get("status"));assertNotNull(first.get("opened_at"));assertEquals(1L,db.queryForObject("SELECT count(*) FROM audit_events WHERE event_type='NOTIFICATION_OPENED'",Long.class));}
    @Test void ownerIsolationAndOpenBodyCannotIntroduceAuthority(){UUID notification=deliver(create("ONCE"));code("NOT_FOUND",()->notifications.get(session,UUID.randomUUID()));code("NOT_FOUND",()->notifications.open(session,UUID.randomUUID(),body(Map.of())));for(String field:List.of("owner_id","opened_at","status","callback"))code("INVALID_REQUEST",()->notifications.open(session,notification,body(Map.of(field,"forbidden"))));var foreign=new AuthService.Session(session.hash(),UUID.randomUUID(),session.reauth(),session.epoch());code("SESSION_REVOKED",()->notifications.get(foreign,notification));assertNull(db.queryForObject("SELECT opened_at FROM notifications WHERE id=?",Object.class,notification));}
    @Test void keysetPagingHasNoDuplicatesAndCursorScopeIsBound(){List<UUID> ids=new ArrayList<>();for(int i=0;i<3;i++)ids.add(deliver(create("ONCE")));var first=notifications.list(session,null,null,2);var items=(List<Map<String,Object>>)first.get("items");assertEquals(2,items.size());assertNotNull(first.get("next_cursor"));var second=notifications.list(session,null,(String)first.get("next_cursor"),2);var rest=(List<Map<String,Object>>)second.get("items");assertEquals(1,rest.size());Set<Object> distinct=new HashSet<>();items.forEach(item->distinct.add(item.get("id")));rest.forEach(item->distinct.add(item.get("id")));assertEquals(3,distinct.size());assertNull(second.get("next_cursor"));code("NOT_FOUND",()->schedules.list(session,null,(String)first.get("next_cursor"),2));}
    @Test void projectFilterCannotReadAnotherProjectAndForeignProjectIsNotFound(){UUID project=UUID.randomUUID();db.update("INSERT INTO projects(id,owner_id,name) VALUES (?,?,'Synthetic project')",project,owner);var definition=definition("ONCE");definition.put("project_id",project);UUID schedule=(UUID)confirm(preview("CREATE",null,null,definition),UUID.randomUUID()).get("schedule_id");UUID notification=deliver(schedule);deliver(create("ONCE"));var filtered=(List<Map<String,Object>>)notifications.list(session,project,null,20).get("items");assertEquals(1,filtered.size());assertEquals(notification,filtered.getFirst().get("id"));code("NOT_FOUND",()->notifications.list(session,UUID.randomUUID(),null,20));}
    @Test void openAuditFailureRollsBackAcknowledgement(){UUID notification=deliver(create("ONCE"));db.execute("ALTER TABLE audit_events ADD CONSTRAINT notification_open_failure CHECK(event_type<>'NOTIFICATION_OPENED')");try{var created=java.time.Instant.parse(notifications.get(session,notification).get("created_at").toString());assertThrows(Exception.class,()->inboxAt(created.plusSeconds(1)).open(session,notification,body(Map.of())));assertEquals("CREATED",notifications.get(session,notification).get("status"));assertNull(db.queryForObject("SELECT opened_at FROM notifications WHERE id=?",Object.class,notification));}finally{db.execute("ALTER TABLE audit_events DROP CONSTRAINT notification_open_failure");}}
    @Test void notificationAndOccurrenceReadViewsHaveOnlyFrozenFields(){UUID schedule=create("ONCE"),notification=deliver(schedule);assertEquals(Set.of("id","occurrence_id","schedule_id","schedule_version","project_id","title","text","planned_fire_at_utc","created_at","opened_at","status","lateness_seconds"),notifications.get(session,notification).keySet());var records=(List<Map<String,Object>>)schedules.occurrences(session,schedule,null,20).get("items");var occurrence=records.getFirst();assertEquals(Set.of("id","schedule_id","schedule_version","planned_fire_at_utc","status","reason_code","notification_id","lateness_seconds","settled_at"),occurrence.keySet());assertEquals("DELIVERED",occurrence.get("status"));assertEquals(notification,occurrence.get("notification_id"));assertNull(occurrence.get("reason_code"));assertNotNull(occurrence.get("settled_at"));assertFalse(Json.canonical(records).contains("sentinel"));}
}
